Definition poison_cells (m : amem) : Prop :=
     rw_cells bsegs m 0xb2118 [C8 (Z_to_bv 64 0x14be28); C8 (Z_to_bv 64 0xb7af8); C8 (Z_to_bv 64 0xba2f8);
                               C8 (Z_to_bv 64 0xbafe8); C8 (Z_to_bv 64 0xbaff0); C8 (Z_to_bv 64 0xbafe0)]
  /\ rw_cells bsegs m 0xb2148 [C8 (Z_to_bv 64 0xb3fa8)]
  /\ rw_cells bsegs m 0xb3fa0 [C8 (Z_to_bv 64 0xab458); C8 (Z_to_bv 64 0xab85c)]
  /\ rw_cells bsegs m 0xba2f8 [C8 (Z_to_bv 64 0x7fff8000)]
  /\ rw_cells bsegs m 0xbafe0 [C8 (Z_to_bv 64 0x7fffffffffff); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0)]
  /\ rw_cells bsegs m 0xb9b5c [C1 (Z_to_bv 8 1)]
  /\ rw_cells bsegs m 0x14bea0 [C8 (Z_to_bv 64 18446744073709551615)].   (* [comment removed for export] *)

Lemma poison_cells_frame : forall m m' W,
  poison_cells m -> munch W m m' -> wmono bsegs m m' ->
